  hand=Inject(match,"CS2_231");BeginCard(hand);InspectMatchCard(match.Card("VAN_CS2_182"));Check(board.Count==6&&pending=="play","Inspecting details does not summon");inspectMatch=false;RenderMatch();ApplyMode(false);RenderMatch();Render(Path.Combine(folder,"39-position-normal.png"));ApplyMode(true);RenderMatch();Render(Path.Combine(folder,"40-position-minimal-six.png"));ApplyTheme(false,false);RenderMatch();Render(Path.Combine(folder,"41-position-wps.png"));ApplyTheme(true,true);RenderMatch();UpdateLayout();foreach(var border in liveUnits){var bounds=border.TransformToAncestor(livePanel).TransformBounds(new Rect(0,0,border.ActualWidth,border.ActualHeight));Check(bounds.Right<=livePanel.ActualWidth+1&&bounds.Bottom<=livePanel.ActualHeight+1,"Placement controls preserve compact board bounds");}ClickRelativeSlot(1,enemy.Id,false);ClickRelativeSlot(0,-999,false);Check(board.Count==6&&pending=="play","Enemy and stale anchors cannot place minions");ClickRelativeSlot(0,a.Id,false);Check(board.Count==7&&board[0].CardId=="VAN_CS2_231"&&board[1].Id==a.Id,"Front placement reaches seven slots");hand=Inject(match,"CS2_231");BeginCard(hand);Check(pending==""&&placementButtons.Count==0&&match.Players[0].Hand.Any(h=>h.Id==hand),"Full board rejects placement before spending");
