  choosePosition=true;match=MatchFixture();ClearPending();hand=Inject(match,"EX1_019");BeginCard(hand);ClickEmptySlot(0,0);Check(match.Players[0].Board.Count==1&&pending=="","Empty board permits targeted battlecry with no eligible target");choosePosition=false;RenderMatch();
