 MatchTarget FirstTestTarget(MatchEngine game,int seat,string mask,bool ability){foreach(var target in game.Characters(1-seat).Reverse().Concat(game.Characters(seat)))try{game.ValidateTarget(seat,target,mask,ability);return target;}catch(InvalidOperationException){}return null;}
}
